{
  "summary": "Gather Acme Cloud Services contract terms, renewal/pricing clauses, SLA performance history, and any credits owed, then draft a reply addressing the proposed 12% increase and renewal terms.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (end date, renewal notice period, pricing/escalation clauses, SLA terms), any pricing or vendor renewal policy documents, recent invoices (convert currency if in USD), and use the SLA credit calculator against Acme's performance logs to determine any SLA misses and credits owed.",
      "why": "The executor needs the exact contract terms, policy constraints, invoice amounts, and any SLA credits owed to craft an informed, accurate response to the renewal and price increase request."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the reply to Acme Cloud Services addressing the 12% price increase, referencing contract terms, any SLA credits owed (to offset costs), and proposing acceptance, negotiation, or counter-terms based on the gathered facts.",
      "why": "The executor synthesizes all retrieved facts into the final vendor-facing response for human review and approval."
    }
  ],
  "escalate": null
}
